   4 import { getAuthenticatedToken } from '@/lib/utils/authUtils';
   5 
   6 interface ApiServiceOptions<T> {
   7   endpoint: string;
   8   method?: 'GET' | 'POST' | 'PUT' | 'DELETE';
   9   data?: T;
  10   token?: string; // Allow passing token directly
  11   user?: FirebaseUser | null; // Or pass the user object
  12   headers?: Record<string, string>;
  13   isFormData?: boolean;
  14 }
  15 
  16 /**
  17  * A unified API service function to handle all client-server communication.
  18  * It automatically handles authentication, request body serialization, and response parsing.
  19  *
  20  * @param options - The configuration for the API request.
  21  * @returns A promise that resolves to the JSON response from the API.
  22  * @throws An error if the request fails or the user is not authenticated when required.
  23  */
  24 export async function apiService<TRequest = any, TResponse = any>(
  25   options: ApiServiceOptions<TRequest>
  26 ): Promise<TResponse> {
  27   const {
  28     endpoint,
  29     method = 'GET',
  30     data,
  31     token: directToken,
  32     user,
  33     headers = {},
  34     isFormData = false,
  35   } = options;
  36 
  37   let authToken = directToken;
  38 
  39   if (!authToken && user) {
  40     authToken = await getAuthenticatedToken(user);
  41   }
  42 
  43   const config: RequestInit = {
  44     method,
  45     headers: { ...headers },
  46   };
  47 
  48   if (authToken) {
  49     config.headers = {
  50       ...config.headers,
  51       'Authorization': `Bearer ${authToken}`,
  52     };
  53   }
  54 
  55   if (data) {
  56     if (isFormData) {
  57       // Don't set Content-Type for FormData, browser does it with boundary
  58       config.body = data as unknown as FormData;
  59     } else {
  60       (config.headers as Record<string, string>)['Content-Type'] = 'application/json';
  61       config.body = JSON.stringify(data);
  62     }
  63   }
  64 
  65   const response = await fetch(endpoint, config);
  66 
  67   if (!response.ok) {
  68     let errorData;
  69     try {
  70       errorData = await response.json();
  71     } catch (e) {
  72       // If the response is not JSON, use the status text
  73       errorData = { message: response.statusText || 'An unknown error occurred.' };
  74     }
  75     throw new Error(errorData.message);
  76   }
  77 
  78   // Handle cases where the response might be empty (e.g., DELETE 204 No Content)
  79   const contentType = response.headers.get('content-type');
  80   if (contentType && contentType.includes('application/json')) {
  81     return response.json();
  82   }
  83   // Return an empty object or a success indicator for non-JSON responses
  84   return {} as TResponse;
  85 }
  86 
