// src/app/api/templates/report/route.ts
import { CreateReportTemplateSchema, type ReportTemplateProperties } from '@/lib/models';
import { createApiResponse, handleApiError, withAuth } from '@/lib/utils/api-utils';
import { defaultReportTemplates } from '@/lib/db/seed-data/report-templates';
import { db } from '@/db';
import { templates } from '@/db/schema';
import { eq } from 'drizzle-orm';

// This is a public endpoint that does not require authentication
// as all users need to be able to fetch the templates for building reports.
export async function GET() {
    try {
        // Fetch report templates from PostgreSQL
        let templateRecords = await db
            .select()
            .from(templates)
            .where(eq(templates.type, 'report'));

        // Lazy seeding if no templates exist
        if (templateRecords.length === 0) {
            // Insert default templates
            for (const template of defaultReportTemplates) {
                await db.insert(templates).values({
                    name: template.name || template.id,
                    description: template.description,
                    category: template.category || 'report',
                    type: 'report',
                    sections: template.content ? JSON.stringify(template.content) : null,
                });
            }

            // Re-fetch after seeding
            templateRecords = await db
                .select()
                .from(templates)
                .where(eq(templates.type, 'report'));
        }

        // Map database records to response format
        const result = templateRecords.map(record => ({
            id: record.id,
            name: record.name,
            description: record.description,
            category: record.category,
            type: record.type,
            content: record.sections ? JSON.parse(record.sections as string) : undefined,
        }));

        return createApiResponse(result, 200);
    } catch (error) {
        return handleApiError(error);
    }
}


export const POST = withAuth(async ({ request }) => {
    try {
        let body = await request.json();
        const validation = CreateReportTemplateSchema.safeParse(body);
        if (!validation.success) {
            return handleApiError(validation.error);
        }

        const { id, name, description, category, content } = validation.data;

        // Check if template with this name already exists
        const existing = await db
            .select()
            .from(templates)
            .where(eq(templates.name, name));

        if (existing.length > 0) {
            return handleApiError({ message: 'A report template with this name already exists.' }, 409);
        }

        // Insert new template
        const result = await db
            .insert(templates)
            .values({
                name: name,
                description: description,
                category: category || 'report',
                type: 'report',
                sections: content ? JSON.stringify(content) : null,
            })
            .returning();

        if (result.length === 0) {
            return handleApiError({ message: 'Failed to create template' }, 500);
        }

        const created = result[0];
        return createApiResponse({
            id: created.id,
            name: created.name,
            description: created.description,
            category: created.category,
            type: created.type,
            content: created.sections ? JSON.parse(created.sections as string) : undefined,
        }, 201);
    } catch (error) {
        return handleApiError(error);
    }
}, { requireAdmin: true });"}

