'use server';

import { createApiResponse, handleApiError } from '@/lib/utils/api-utils';
import { z } from 'zod';
import { db } from '@/db';
import { users } from '@/db/schema';
import { eq } from 'drizzle-orm';
import bcrypt from 'bcryptjs';

const signupSchema = z.object({
    email: z.string().email("Invalid email address"),
    password: z.string().min(6, "Password must be at least 6 characters long"),
    name: z.string().min(1, "Name is required"),
});

/**
 * API endpoint for creating a new user in PostgreSQL.
 * Uses bcrypt for password hashing.
 */
export async function POST(req: Request) {
    try {
        const body = await req.json();
        const validation = signupSchema.safeParse(body);
        if (!validation.success) {
            return handleApiError(validation.error);
        }

        const { email, password, name } = validation.data;

        // Check if user already exists
        const existingUser = await db
            .select()
            .from(users)
            .where(eq(users.email, email));

        if (existingUser.length > 0) {
            return handleApiError({ message: "Email address is already in use by another account." }, 409);
        }

        // Hash password
        const hashedPassword = await bcrypt.hash(password, 10);

        // Create the user in PostgreSQL
        const result = await db
            .insert(users)
            .values({
                email,
                password: hashedPassword,
                name,
                role: 'user',
                credits: 10, // Default credits for new users
                language: 'en',
            })
            .returning();

        if (result.length === 0) {
            return handleApiError({ message: 'Failed to create user' }, 500);
        }

        const createdUser = result[0];
        return createApiResponse({ 
            user: { 
                id: createdUser.id, 
                email: createdUser.email,
                name: createdUser.name 
            } 
        }, 201);

    } catch (error: any) {
        return handleApiError(error);
    }
}"}

