   6 interface ApiServiceOptions<T> {
   7   endpoint: string;
   8   method?: 'GET' | 'POST' | 'PUT' | 'DELETE';
   9   data?: T;
  10   token?: string; // Allow passing token directly
  11   user?: FirebaseUser | null; // Or pass the user object
  12   headers?: Record<string, string>;
  13   isFormData?: boolean;
  14 }
