'use server';
import type { UserProfile } from '@/lib/models';
import { db } from '@/db';
import { users } from '@/db/schema';
import { eq, desc, gt } from 'drizzle-orm';
import bcrypt from 'bcryptjs';

export async function getUserProfile(id: string | number): Promise<UserProfile | null> {
    if (!id) return null;

    const userId = typeof id === 'string' ? parseInt(id) : id;

    const result = await db
        .select()
        .from(users)
        .where(eq(users.id, userId));

    if (result.length === 0) return null;

    const user = result[0];
    return {
        id: user.id.toString(),
        name: user.name || '',
        email: user.email,
        role: user.role as any,
        credits: user.credits || 10,
        language: user.language || 'en',
        photoURL: user.photoURL || '',
        createdAt: user.createdAt?.toISOString() || new Date().toISOString(),
        updatedAt: user.updatedAt?.toISOString() || new Date().toISOString(),
        hasCompletedOnboarding: false,
        bio: '',
        profilePictureUrl: user.photoURL || '',
        lastDailyCreditUpdate: new Date(0).toISOString(),
        apiKeys: {},
    } as UserProfile;
}

export async function getPaginatedUsers({ limit, lastVisibleId }: { limit: number, lastVisibleId?: string }) {
    const lastId = lastVisibleId ? parseInt(lastVisibleId) : 0;

    const result = await db
        .select()
        .from(users)
        .where(gt(users.id, lastId))
        .orderBy(desc(users.createdAt))
        .limit(limit + 1);

    const userList = result.slice(0, limit).map(user => ({
        id: user.id.toString(),
        name: user.name || '',
        email: user.email,
        role: user.role,
        credits: user.credits || 10,
        language: user.language || 'en',
        photoURL: user.photoURL || '',
        createdAt: user.createdAt?.toISOString() || new Date().toISOString(),
        updatedAt: user.updatedAt?.toISOString() || new Date().toISOString(),
    } as any));

    const hasNextPage = result.length > limit;
    const newLastVisibleId = hasNextPage ? result[limit - 1].id.toString() : null;

    return { users: userList, hasNextPage, lastVisibleId: newLastVisibleId };
}

export async function createUser(data: Omit<UserProfile, 'id' | 'createdAt' | 'updatedAt'> & { password?: string }): Promise<{ user: { id?: number, uid?: string, email?: string } }> {
    const { email, password, name, role, credits } = data;

    if (!email || !password) {
        throw new Error("Email and password are required");
    }

    // Hash password
    const hashedPassword = await bcrypt.hash(password, 10);

    // Create user in PostgreSQL
    const result = await db
        .insert(users)
        .values({
            email,
            password: hashedPassword,
            name,
            role: role as 'user' | 'admin',
            credits: credits || 10,
            language: 'en',
        })
        .returning();

    if (result.length === 0) {
